<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{{ $invoice->invoice_number }}</title><style>body{font-family:Arial,sans-serif;max-width:850px;margin:40px auto;color:#14213d}header{display:flex;justify-content:space-between;border-bottom:3px solid #c79a35;padding-bottom:20px}table{width:100%;border-collapse:collapse;margin-top:30px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.total{text-align:right;font-size:1.3rem;margin-top:24px}</style></head><body><header><div><h1>Horus Media</h1><p>Direct advertising invoice</p></div><div><strong>{{ $invoice->invoice_number }}</strong><br>Issued {{ $invoice->issued_on }}<br>Due {{ $invoice->due_on }}</div></header><h2>Bill to</h2><p>{{ $invoice->billingProfile?->legal_name ?? $invoice->advertiser->legal_name }}<br>{{ $invoice->billingProfile?->billing_email ?? $invoice->advertiser->billing_email }}</p><table><thead><tr><th>Description</th><th>Pricing</th><th>Amount</th></tr></thead><tbody>@foreach($invoice->line_items as $item)<tr><td>{{ $item['description'] }}</td><td>{{ $item['pricing_model'] }}</td><td>{{ $invoice->currency }} {{ number_format($item['amount_minor']/100,2) }}</td></tr>@endforeach</tbody></table><div class="total">Subtotal: {{ $invoice->currency }} {{ number_format($invoice->subtotal_minor/100,2) }}<br>Tax: {{ $invoice->currency }} {{ number_format($invoice->tax_minor/100,2) }}<br><strong>Total: {{ $invoice->currency }} {{ number_format($invoice->total_minor/100,2) }}</strong></div></body></html>
